oxy_webhelp_navlinks = {"configure_db2_protection-d39536e34449":{"topics":[{"title":"Creating a custom SLA Domain for Db2","shortdesc":"<p class=\"shortdesc\">Create a custom SLA Domain to define the backup frequency, retention, and archival         policies for your Db2 workloads.<\/p>","href":"db2\/creating_custom_sla_db2.html","attributes":{"data-id":"creating_custom_sla_db2"},"menu":{"hasChildren":false},"tocID":"creating_custom_sla_db2-d39536e34460","topics":[]},{"title":"Assigning protection to Db2 objects","shortdesc":"<p class=\"shortdesc\">To protect Db2 databases, manage protection by selecting an SLA Domain with defined         data protection         policies.<\/p>","href":"db2\/assigning_protection_db2_objects.html","attributes":{"data-id":"assigning_protection_db2_objects"},"menu":{"hasChildren":false},"tocID":"assigning_protection_db2_objects-d39536e34471","topics":[]},{"title":"Taking an on-demand snapshot of a Db2 database","shortdesc":"<p class=\"shortdesc\">Take an on-demand snapshot of a Db2 database to protect critical data and ensure         backups are available for recovery before high-risk tasks, peak activity, or maintenance         windows.<\/p>","href":"db2\/taking_on_demand_snapshot_db2_db.html","attributes":{"data-id":"taking_on_demand_snapshot_db2_db"},"menu":{"hasChildren":false},"tocID":"taking_on_demand_snapshot_db2_db-d39536e34482","topics":[]},{"title":"Changing retention policy of a Db2 snapshot","shortdesc":"<p class=\"shortdesc\">You can change the retention policy of a Db2 snapshot to optimize storage and data         accessibility of Db2 databases. The SLA Domain policy retains snapshots for the maximum SLA         Domain period, while the Forever retention policy retains snapshots until you delete them         manually.<\/p>","href":"db2\/changing_retention_db2_snapshot.html","attributes":{"data-id":"changing_retention_db2_snapshot"},"menu":{"hasChildren":false},"tocID":"changing_retention_db2_snapshot-d39536e34493","topics":[]},{"title":"Legal hold for Db2 snapshots","shortdesc":"<p class=\"shortdesc\">Legal hold ensures that snapshots required for litigation are protected for the         duration of the legal hold, providing a compliant and efficient way to manage data subject         to legal obligations.<\/p>","href":"db2\/legal_hold_db2_snapshots.html","attributes":{"data-id":"legal_hold_db2_snapshots"},"menu":{"hasChildren":false},"tocID":"legal_hold_db2_snapshots-d39536e34504","next":"legal_hold_db2_snapshots-d39536e34504"},{"title":"Configuring parallelism in Db2","shortdesc":"<p class=\"shortdesc\">To optimize Db2 backup performance, configure parallel reading across multiple table         spaces. This enables simultaneous backup streams, minimizing database downtime and         maximizing resource utilization.<\/p>","href":"db2\/configuring_parallelism_db2.html","attributes":{"data-id":"configuring_parallelism_db2"},"menu":{"hasChildren":false},"tocID":"configuring_parallelism_db2-d39536e34537","topics":[]},{"title":"Configuring multiple concurrent sessions in Db2","shortdesc":"<p class=\"shortdesc\">To optimize Db2 backup performance, configure multiple concurrent sessions for         simultaneous tasks. This reduces downtime and maximizes resource utilization.<\/p>","href":"db2\/configuring_multiple_concurrent_sessions_db2.html","attributes":{"data-id":"configuring_multiple_concurrent_sessions_db2"},"menu":{"hasChildren":false},"tocID":"configuring_multiple_concurrent_sessions_db2-d39536e34548","topics":[]},{"title":"Configuring compression for Db2 databases","shortdesc":"<p class=\"shortdesc\">To reduce the storage footprint of Db2 backups, configure compression at the source         for individual Db2 databases.<\/p>","href":"db2\/configuring_compression_db2.html","attributes":{"data-id":"configuring_compression_db2"},"menu":{"hasChildren":false},"tocID":"configuring_compression_db2-d39536e34559","topics":[]}]}};